-- =============================================================================
-- Migration V16: Phụ phí phát sinh / báo giá điều chỉnh tại hiện trường (bảng ngoài ERD)
-- SUPERVISOR báo sai lệch → DISPATCHER chốt giá, gửi khách → khách xác nhận / từ chối
-- Khách xác nhận → cộng bookings.total_amount; người vận chuyển thu tiền mặt → tạo phiếu thu payments (payment_id)
-- =============================================================================
CREATE TABLE IF NOT EXISTS "booking_surcharges" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "schedule_id" int,
  "incident_id" int,
  "service_id" int,
  "surcharge_type" varchar(30) NOT NULL,
  "description" text NOT NULL,
  "quantity" int NOT NULL DEFAULT 1,
  "unit_price" decimal(12,2) NOT NULL,
  "amount" decimal(12,2) NOT NULL,
  "status" varchar(30) NOT NULL DEFAULT 'PROPOSED',
  "requested_by" bigint,                         -- trưởng nhóm đề xuất, hoặc điều phối viên tự tạo
  "requested_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "reviewed_by" bigint,                          -- điều phối viên chốt giá / bác bỏ / rút lại
  "reviewed_at" timestamp,
  "review_note" text,
  "sent_to_customer_at" timestamp,
  "customer_responded_at" timestamp,
  "customer_note" text,                          -- lý do khách từ chối
  "collected_by" bigint,                         -- người vận chuyển đã thu tiền
  "collected_at" timestamp,
  "payment_id" int,                              -- phiếu thu tiền mặt tạo khi thu tiền
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_booking_surcharges_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surcharges_schedule FOREIGN KEY ("schedule_id") REFERENCES "moving_schedules" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surcharges_incident FOREIGN KEY ("incident_id") REFERENCES "incidents" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surcharges_service FOREIGN KEY ("service_id") REFERENCES "services" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surcharges_requested_by FOREIGN KEY ("requested_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surcharges_reviewed_by FOREIGN KEY ("reviewed_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surcharges_collected_by FOREIGN KEY ("collected_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surcharges_payment FOREIGN KEY ("payment_id") REFERENCES "payments" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_booking_surcharges_type CHECK (surcharge_type IN
    ('EXTRA_FLOOR', 'NO_ELEVATOR', 'LONG_CARRY', 'EXTRA_ITEMS', 'WAITING_TIME', 'EXTRA_DISTANCE',
     'DISASSEMBLY', 'PACKING_MATERIAL', 'OTHER')),
  CONSTRAINT chk_booking_surcharges_status CHECK (status IN
    ('PROPOSED', 'WAITING_CUSTOMER', 'ACCEPTED', 'REJECTED', 'REJECTED_BY_CUSTOMER', 'CANCELLED')),
  CONSTRAINT chk_booking_surcharges_quantity CHECK (quantity > 0),
  CONSTRAINT chk_booking_surcharges_amounts CHECK (unit_price > 0 AND amount = quantity * unit_price),
  CONSTRAINT chk_booking_surcharges_sent CHECK (status NOT IN ('WAITING_CUSTOMER', 'ACCEPTED', 'REJECTED_BY_CUSTOMER') OR sent_to_customer_at IS NOT NULL),
  CONSTRAINT chk_booking_surcharges_responded CHECK (status NOT IN ('ACCEPTED', 'REJECTED_BY_CUSTOMER') OR customer_responded_at IS NOT NULL),
  CONSTRAINT chk_booking_surcharges_collected CHECK (collected_at IS NULL OR (status = 'ACCEPTED' AND payment_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_booking_surcharges_booking_status ON "booking_surcharges" ("booking_id", "status");
CREATE INDEX IF NOT EXISTS idx_booking_surcharges_schedule ON "booking_surcharges" ("schedule_id");
CREATE INDEX IF NOT EXISTS idx_booking_surcharges_status ON "booking_surcharges" ("status", "requested_at");
